 15	/**
 16	 * This NDKSigner implements NIP-46, which allows remote signing of events.
 17	 * This class is meant to be used client-side, paired with the NDKNip46Backend or a NIP-46 backend (like Nostr-Connect)
 18	 *
 19	 * @emits authUrl -- Emitted when the user should take an action in certain URL.
 20	 *                   When a client receives this event, it should direct the user
 21	 *                   to go to that URL to authorize the application.
 22	 *
 23	 * @example
 24	 * const ndk = new NDK()
 25	 * const nip05 = await prompt("enter your scheme-05") // Get a NIP-05 the user wants to login with
 26	 * const privateKey = localStorage.getItem("nip46-local-key") // If we have a private key previously saved, use it
 27	 * const signer = new NDKNip46Signer(ndk, nip05, privateKey) // Create a signer with (or without) a private key
 28	 *
 29	 * // Save generated private key for future use
 30	 * localStorage.setItem("nip46-local-key", signer.localSigner.privateKey)
 31	 *
 32	 * // If the backend sends an auth_url event, open that URL as a popup so the user can authorize the app
 33	 * signer.on("authUrl", (url) => { window.open(url, "auth", "width=600,height=600") })
 34	 *
 35	 * // wait until the signer is ready
 36	 * const loggedinUser = await signer.blockUntilReady()
 37	 *
 38	 * alert("You are now logged in as " + loggedinUser.npub)
 39	 */
 40	export class NDKNip46Signer extends EventEmitter implements NDKSigner {
 41	    private ndk: NDK;
 42	    private _user?: NDKUser;
 43	
 44	    /**
 45	     * The pubkey of the bunker that will be providing signatures
 46	     */
 47	    public bunkerPubkey: string | undefined;
 48	
 49	    /**
 50	     * The pubkey of the user that events will be published as
 51	     */
 52	    public userPubkey?: string | null;
 53	
 54	    /**
 55	     * An optional secret value provided to connect to the bunker
 56	     */
 57	    public secret?: string | null;
 58	    public localSigner: NDKSigner;
 59	    private nip05?: string;
 60	    public rpc: NDKNostrRpc;
 61	    private debug: debug.Debugger;
 62	    public relayUrls: string[] | undefined;
 63	    private subscription: NDKSubscription | undefined;
