 65	    /**
 66	     * @param ndk - The NDK instance to use
 67	     * @param remoteNip05 - The nip05 that wants to be published as
 68	     * @param localSigner - The signer that will be used to request events to be signed
 69	     */
 70	    public constructor(ndk: NDK, remoteNip05: string, localSigner?: NDKSigner);
