 72	    /**
 73	     * @param ndk - The NDK instance to use
 74	     * @param userOrConnectionToken - The public key, or a connection token, of the npub that wants to be published as
 75	     * @param localSigner - The signer that will be used to request events to be signed
 76	     */
 77	    public constructor(ndk: NDK, userOrConnectionToken: string, localSigner?: NDKSigner) {
 78	        super();
 79	
 80	        this.ndk = ndk;
 81	        this.debug = ndk.debug.extend("nip46:signer");
 82	
 83	        if (userOrConnectionToken.startsWith("bunker://")) {
 84	            this.connectionTokenInit(userOrConnectionToken);
 85	        } else {
 86	            this.nip05Init(userOrConnectionToken);
 87	        }
 88	
 89	        if (!localSigner) {
 90	            this.localSigner = NDKPrivateKeySigner.generate();
 91	        } else {
 92	            this.localSigner = localSigner;
 93	        }
 94	
 95	        this.rpc = new NDKNostrRpc(this.ndk, this.localSigner, this.debug, this.relayUrls);
 96	    }
