 98	    private connectionTokenInit(connectionToken: string) {
 99	        const bunkerUrl = new URL(connectionToken);
100	        const bunkerPubkey = bunkerUrl.hostname || bunkerUrl.pathname.replace(/^\/\//, "");
101	        const userPubkey = bunkerUrl.searchParams.get("pubkey");
102	        const relayUrls = bunkerUrl.searchParams.getAll("relay");
103	        const secret = bunkerUrl.searchParams.get("secret");
104	
105	        this.bunkerPubkey = bunkerPubkey;
106	        this.userPubkey = userPubkey;
107	        this.relayUrls = relayUrls;
108	        this.secret = secret;
109	    }
110	
111	    private nip05Init(nip05: string) {
112	        this.nip05 = nip05;
113	    }
114	
115	    /**
116	     * @deprecated Use userPubkey instead
117	     */
118	    get remotePubkey() {
119	        return this.userPubkey;
120	    }
