122	    /**
123	     * We start listening for events from the bunker
124	     */
125	    private async startListening() {
126	        if (this.subscription) return;
127	
128	        const localUser = await this.localSigner.user();
129	
130	        if (!localUser) throw new Error("Local signer not ready");
131	
132	        this.subscription = await this.rpc.subscribe({
133	            kinds: [NDKKind.NostrConnect],
134	            "#p": [localUser.pubkey],
135	        });
136	    }
