139	     * Get the user that is being published as
140	     */
141	    public async user(): Promise<NDKUser> {
142	        if (!this._user && !this.userPubkey) throw new Error("Remote user not ready");
143	        this._user ??= new NDKUser({ pubkey: this.userPubkey! });
144	        return this._user;
145	    }
