147	    public async blockUntilReady(): Promise<NDKUser> {
148	        if (this.nip05 && !this.userPubkey) {
149	            const user = await NDKUser.fromNip05(this.nip05, this.ndk);
150	
151	            if (user) {
152	                this._user = user;
153	                this.userPubkey = user.pubkey;
154	                this.relayUrls = user.nip46Urls;
155	                this.rpc = new NDKNostrRpc(this.ndk, this.localSigner, this.debug, this.relayUrls);
156	            }
157	        }
158	
159	        if (!this.bunkerPubkey && this.userPubkey) {
160	            this.bunkerPubkey = this.userPubkey;
161	        } else if (!this.bunkerPubkey) {
162	            throw new Error("Bunker pubkey not set");
163	        }
164	
165	        await this.startListening();
166	
167	        this.rpc.on("authUrl", (...props) => {
168	            this.emit("authUrl", ...props);
169	        });
170	
171	        return new Promise((resolve, reject) => {
172	            const connectParams = [this.userPubkey ?? ""];
173	
174	            if (this.secret) connectParams.push(this.secret);
175	
176	            if (!this.bunkerPubkey) throw new Error("Bunker pubkey not set");
177	
178	            this.rpc.sendRequest(
179	                this.bunkerPubkey,
180	                "connect",
181	                connectParams,
182	                24133,
183	                (response: NDKRpcResponse) => {
184	                    if (response.result === "ack") {
185	                        this.getPublicKey().then((pubkey) => {
186	                            this.userPubkey = pubkey;
187	                            this._user = new NDKUser({ pubkey });
188	                            resolve(this._user);
189	                        });
190	                    } else {
191	                        reject(response.error);
192	                    }
193	                }
194	            );
195	        });
196	    }
