198	    public async getPublicKey(): Promise<Hexpubkey> {
199	        if (this.userPubkey) return this.userPubkey;
200	
201	        return new Promise<Hexpubkey>((resolve, reject) => {
202	            if (!this.bunkerPubkey) throw new Error("Bunker pubkey not set");
203	
204	            this.rpc.sendRequest(
205	                this.bunkerPubkey,
206	                "get_public_key",
207	                [],
208	                24133,
209	                (response: NDKRpcResponse) => {
210	                    resolve(response.result);
211	                }
212	            );
213	        });
214	    }
