221	    public async encrypt(recipient: NDKUser, value: string, scheme: NDKEncryptionScheme = 'nip04'): Promise<string> {
222	        return this.encryption(recipient, value, scheme, "encrypt");
223	    }
224	
225	    public async decrypt(sender: NDKUser, value: string, scheme: NDKEncryptionScheme = 'nip04'): Promise<string> {
226	        return this.encryption(sender, value, scheme, "decrypt");
227	    }
