229	    private async encryption(
230	        peer: NDKUser,
231	        value: string,
232	        scheme: NDKEncryptionScheme,
233	        method: EncryptionMethod
234	    ): Promise<string> {
235	        const promise = new Promise<string>((resolve, reject) => {
236	            if (!this.bunkerPubkey) throw new Error("Bunker pubkey not set");
237	
238	            this.rpc.sendRequest(
239	                this.bunkerPubkey,
240	                `${scheme}_${method}`,
241	                [peer.pubkey, value],
242	                24133,
243	                (response: NDKRpcResponse) => {
244	                    if (!response.error) {
245	                        resolve(response.result);
246	                    } else {
247	                        reject(response.error);
248	                    }
249	                }
250	            );
251	        });
252	
253	        return promise;
254	    }
