256	    public async sign(event: NostrEvent): Promise<string> {
257	        const promise = new Promise<string>((resolve, reject) => {
258	            if (!this.bunkerPubkey) throw new Error("Bunker pubkey not set");
259	
260	            this.rpc.sendRequest(
261	                this.bunkerPubkey,
262	                "sign_event",
263	                [JSON.stringify(event)],
264	                24133,
265	                (response: NDKRpcResponse) => {
266	                    if (!response.error) {
267	                        const json = JSON.parse(response.result);
268	                        resolve(json.sig);
269	                    } else {
270	                        reject(response.error);
271	                    }
272	                }
273	            );
274	        });
275	
276	        return promise;
277	    }
