279	    /**
280	     * Allows creating a new account on the remote server.
281	     * @param username Desired username for the NIP-05
282	     * @param domain Desired domain for the NIP-05
283	     * @param email Email address to associate with this account -- Remote servers may use this for recovery
284	     * @returns The public key of the newly created account
285	     */
286	    public async createAccount(
287	        username?: string,
288	        domain?: string,
289	        email?: string
290	    ): Promise<Hexpubkey> {
291	        await this.startListening();
292	        const req: string[] = [];
293	
294	        if (username) req.push(username);
295	        if (domain) req.push(domain);
296	        if (email) req.push(email);
297	
298	        return new Promise<Hexpubkey>((resolve, reject) => {
299	            if (!this.bunkerPubkey) throw new Error("Bunker pubkey not set");
300	
301	            this.rpc.sendRequest(
302	                this.bunkerPubkey,
303	                "create_account",
304	                req,
305	                NDKKind.NostrConnect,
306	                (response: NDKRpcResponse) => {
307	                    if (!response.error) {
308	                        const pubkey = response.result;
309	                        resolve(pubkey);
310	                    } else {
311	                        reject(response.error);
312	                    }
