 32	export class NDKNostrRpc extends EventEmitter {
 33	    private ndk: NDK;
 34	    private signer: NDKSigner;
 35	    private relaySet: NDKRelaySet | undefined;
 36	    private debug: debug.Debugger;
 37	    public encryptionType: "nip04" | "nip44" = "nip04";
 38	    private pool: NDKPool | undefined;
 39	
 40	    public constructor(ndk: NDK, signer: NDKSigner, debug: debug.Debugger, relayUrls?: string[]) {
 41	        super();
 42	        this.ndk = ndk;
 43	        this.signer = signer;
 44	
 45	        // if we have relays, we create a separate pool for it
 46	        if (relayUrls) {
 47	            this.pool = new NDKPool(
 48	                relayUrls,
 49	                [],
 50	                ndk,
 51	                {
 52	                    debug: debug.extend("rpc-pool"),
 53	                    name: "Nostr RPC"
 54	                }
 55	            );
 56	
 57	            this.relaySet = new NDKRelaySet(new Set(), ndk, this.pool);
 58	            for (const url of relayUrls) {
 59	                const relay = this.pool.getRelay(url, false, false);
 60	                relay.authPolicy = NDKRelayAuthPolicies.signIn({ ndk, signer, debug });
 61	                this.relaySet.addRelay(relay);
 62	                relay.connect();
 63	            }
 64	        }
 65	
 66	        this.debug = debug.extend("rpc");
 67	    }
 68	
 69	    /**
 70	     * Subscribe to a filter. This function will resolve once the subscription is ready.
 71	     */
 72	    public subscribe(filter: NDKFilter): Promise<NDKSubscription> {
 73	        const sub = this.ndk.subscribe(
 74	            filter,
 75	            {
 76	                closeOnEose: false,
 77	                groupable: false,
 78	                cacheUsage: NDKSubscriptionCacheUsage.ONLY_RELAY,
 79	                pool: this.pool,
 80	            },
 81	            this.relaySet,
 82	            false
 83	        );
 84	
 85	        sub.on("event", async (event: NDKEvent) => {
 86	            try {
 87	                const parsedEvent = await this.parseEvent(event);
 88	                if ((parsedEvent as NDKRpcRequest).method) {
 89	                    this.emit("request", parsedEvent);
 90	                } else {
 91	                    this.emit(`response-${parsedEvent.id}`, parsedEvent);
 92	                }
 93	            } catch (e) {
 94	                this.debug("error parsing event", e, event.rawEvent());
 95	            }
 96	        });
 97	
 98	        return new Promise((resolve) => {
 99	            sub.on("eose", () => {
100	                this.debug("eosed");
101	                resolve(sub);
102	            });
103	            sub.start();
104	        });
105	    }
