107	    public async parseEvent(event: NDKEvent): Promise<NDKRpcRequest | NDKRpcResponse> {
108	        // support both nip04 and nip44 encryption
109	        if (this.encryptionType === 'nip44' && event.content.includes('?iv=')) {
110	            this.encryptionType = 'nip04';
111	        } else if (this.encryptionType === 'nip04' && !event.content.includes('?iv=')) {
112	            this.encryptionType = 'nip44';
113	        }
114	
115	        const remoteUser = this.ndk.getUser({ pubkey: event.pubkey });
116	        remoteUser.ndk = this.ndk;
117	        let decryptedContent: string;
118	
119	        try {
120	            decryptedContent = await this.signer.decrypt(
121	                remoteUser,
122	                event.content,
123	                this.encryptionType
124	            );
125	        } catch (e) {
126	            const otherEncryptionType = this.encryptionType === 'nip04' ? 'nip44' : 'nip04';
127	            decryptedContent = await this.signer.decrypt(remoteUser, event.content, otherEncryptionType);
128	            this.encryptionType = otherEncryptionType;
129	        }
130	        
131	        const parsedContent = JSON.parse(decryptedContent);
132	        const { id, method, params, result, error } = parsedContent;
133	
134	        if (method) {
135	            return { id, pubkey: event.pubkey, method, params, event };
136	        } else {
137	            return { id, result, error, event };
138	        }
139	    }
