141	    public async sendResponse(
142	        id: string,
143	        remotePubkey: string,
144	        result: string,
145	        kind = NDKKind.NostrConnect,
146	        error?: string
147	    ): Promise<void> {
148	        const res = { id, result } as NDKRpcResponse;
149	        if (error) {
150	            res.error = error;
151	        }
152	
153	        const localUser = await this.signer.user();
154	        const remoteUser = this.ndk.getUser({ pubkey: remotePubkey });
155	        const event = new NDKEvent(this.ndk, {
156	            kind,
157	            content: JSON.stringify(res),
158	            tags: [["p", remotePubkey]],
159	            pubkey: localUser.pubkey,
160	        } as NostrEvent);
161	        
162	        event.content = await this.signer.encrypt(remoteUser, event.content, this.encryptionType);
163	        await event.sign(this.signer);
164	        await event.publish(this.relaySet);
165	    }
