167	    /**
168	     * Sends a request.
169	     * @param remotePubkey
170	     * @param method
171	     * @param params
172	     * @param kind
173	     * @param id
174	     */
175	    public async sendRequest(
176	        remotePubkey: string,
177	        method: string,
178	        params: string[] = [],
179	        kind = 24133,
180	        cb?: (res: NDKRpcResponse) => void
181	    ): Promise<NDKRpcResponse> {
182	        const id = Math.random().toString(36).substring(7);
183	        const localUser = await this.signer.user();
184	        const remoteUser = this.ndk.getUser({ pubkey: remotePubkey });
185	        const request = { id, method, params };
186	        const promise = new Promise<NDKRpcResponse>(() => {
187	            const responseHandler = (response: NDKRpcResponse) => {
188	                if (response.result === "auth_url") {
189	                    this.once(`response-${id}`, responseHandler);
190	                    this.emit("authUrl", response.error);
191	                } else if (cb) {
192	                    cb(response);
193	                }
194	            };
195	
196	            this.once(`response-${id}`, responseHandler);
197	        });
198	
199	        const event = new NDKEvent(this.ndk, {
200	            kind,
201	            content: JSON.stringify(request),
202	            tags: [["p", remotePubkey]],
203	            pubkey: localUser.pubkey,
204	        } as NostrEvent);
205	
206	        event.content = await this.signer.encrypt(remoteUser, event.content, this.encryptionType);
207	        await event.sign(this.signer);
208	        await event.publish(this.relaySet);
209	
210	        return promise;
211	    }
